def illustration(i):
 colors=['#658b92','#a47a62','#77875c','#766c92','#ad8d50']
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="800" height="450" viewBox="0 0 800 450"><rect width="800" height="450" fill="{colors[i%5]}"/><circle cx="620" cy="100" r="65" fill="#f3e3bd"/><path d="M0 340L210 140L420 330L570 210L800 390V450H0Z" fill="#233f48"/><path d="M0 400L280 290L550 410L800 330V450H0Z" fill="#172b32"/></svg>'
 return 'data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()

NAMES=['Maya Chen','Alex Rivera','Priya Shah','Jordan Park','Sam Morgan','Lina Costa','Noah Patel','Eva Brooks','Theo Reed','Ari Kim','Nora Ali','Kai Wilson']
TEXTS=['A few moments from the community garden today. Small changes, shared spaces, and good conversations.','What is one idea that changed how you approach a creative project? Sharing a few notes from this week.','A quiet morning by the coast. Always find something new when I take the long way home.','Our local reading group is collecting recommendations. What should be on the next list?','Behind the scenes at the studio: testing new materials and learning from the first attempt.','A useful reminder to make space for rest as well as progress. Here is what worked for me this week.','The weekend walking route is ready. A river path, a small café, and a view worth stopping for.','New sketchbook pages. Exploring light, colour and the shapes we usually walk past.']
def avatar(i):
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><rect width="80" height="80" rx="40" fill="{["#477c9a","#9d647d","#657d4b","#9b7851"][i%4]}"/><circle cx="40" cy="29" r="15" fill="#f1d4b5"/><path d="M12 80V68a28 28 0 0156 0v12" fill="#29394b"/></svg>'
 return 'data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()

def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 people=[{'name':NAMES[i%12],'email':NAMES[i%12].lower().replace(' ','.')+'@example.test','avatar':avatar(i),'image':illustration(i+sample_index),'role':'Host' if i==0 else 'Co-host' if i==1 else 'Participant','muted':i%3!=0,'hand':i in [3,7,9]} for i in range(18)]
 titles=['Design review','Weekly planning','Research catch-up','Product workshop','Community roundtable','Project handover','Team retrospective','Learning session']
 rows=[{'title':titles[(i+sample_index)%8],'time':f'{9+i%9:02d}:00','duration':30+(i%3)*15,'id':f'830 4100 {2300+i}','date':f'2026-11-{2+i:02d}','host':people[i%12]['name'],'image':illustration(i+sample_index),'size':f'{120+i*31} MB','status':'Processing' if i==2 else 'Ready'} for i in range(18)]
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'popup_mode':None,'keyboard_visible':False,'rows':rows,'people':people,'query':'design','sample_index':sample_index}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d.update(state=state,popup_visible=state in MODALS,popup_mode='modal' if state in MODALS else PANELS.get(state),keyboard_visible=state=='typing')
 if state=='empty':d['rows']=[]
 return d
